import { Cache } from '../vendor/lruish/cache.mjs';

export class Registry {
  constructor() {
    this.connections = new Map();
    this.entries = new Cache({
      onEvict: (key, entry) => {
        this.connections.get(key)?.close();
      },
    });
  }

  connect(id, connection) {
    this.connections.set(id, connection);
    this.entries.set(id, { connected: true });
  }

  disconnect(id) {
    this.connections.get(id)?.close();
    this.connections.delete(id);
    this.entries.evict(id);
  }

  reconnect(id, connection) {
    this.disconnect(id);
    this.connect(id, connection);
  }
}
